<?php
require_once __DIR__ . '/../../../App/auth.php';require_login();$pdo=db();$id=(int)($_GET['id']??0);
$st=$pdo->prepare("SELECT f.*,dp.nome_completo FROM ferias f JOIN dados_pessoais dp ON dp.id_especialista=f.id_especialista WHERE f.id_ferias=?");$st->execute([$id]);$feria=$st->fetch();if(!$feria){header('Location: especialistas.php');exit;}$erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){$inicio=$_POST['data_inicio']??'';$fim=$_POST['data_fim']??'';$estado=$_POST['estado']??'PROGRAMADA';$obs=trim($_POST['observacoes']??'');if(!$inicio||!$fim||$fim<$inicio)$erro='Informe um período válido.';else{$dias=(int)((strtotime($fim)-strtotime($inicio))/86400)+1;$up=$pdo->prepare("UPDATE ferias SET ano=?,data_inicio=?,data_fim=?,numero_dias=?,estado=?,observacoes=? WHERE id_ferias=?");$up->execute([(int)($_POST['ano']??date('Y')),$inicio,$fim,$dias,$estado,$obs,$id]);header('Location: especialista.php?id='.(int)$feria['id_especialista'].'#ferias');exit;}}
$page_title='Editar Férias';require __DIR__.'/../../layout/header.php';?>
<div class="module-page"><div class="panel form-panel"><h2>Editar período de férias</h2><p><strong><?=htmlspecialchars($feria['nome_completo'])?></strong></p><?php if($erro):?><div class="erro"><?=htmlspecialchars($erro)?></div><?php endif;?><form method="post" class="form-grid"><label>Ano<input type="number" name="ano" value="<?=htmlspecialchars($feria['ano'])?>" required></label><label>Data de início<input type="date" name="data_inicio" value="<?=htmlspecialchars($feria['data_inicio'])?>" required></label><label>Data de fim<input type="date" name="data_fim" value="<?=htmlspecialchars($feria['data_fim'])?>" required></label><label>Estado<select name="estado"><?php foreach(['PROGRAMADA','EM_CURSO','CONCLUIDA','CANCELADA'] as $e):?><option <?=$feria['estado']===$e?'selected':''?>><?=$e?></option><?php endforeach;?></select></label><label class="full">Observações<textarea name="observacoes" rows="4"><?=htmlspecialchars($feria['observacoes']??'')?></textarea></label><div class="actions full"><button class="btn btn-primary">Atualizar</button><a class="btn btn-secondary" href="especialista.php?id=<?=(int)$feria['id_especialista']?>#ferias">Cancelar</a></div></form></div></div>
<?php require __DIR__.'/../../layout/footer.php'; ?>
